use std::path::{Path, PathBuf};
use crate::file_searcher::{FileSearcher, SearchMatch};
use regex::Regex;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InputMode {
    Search,
    Replace,
    List,
}

#[derive(Clone, Debug)]
pub struct FileResult {
    pub path: PathBuf,
    pub matches: Vec<SearchMatch>,
    pub selected: bool,
    pub expanded: bool,
}

pub struct App {
    pub project_root: PathBuf,
    pub search_input: String,
    pub replace_input: String,
    pub input_mode: InputMode,
    pub search_mode: SearchMode,
    pub replace_mode: ReplaceMode,
    pub file_results: Vec<FileResult>,
    pub selected_file_idx: usize,
    pub selected_match_idx: Option<usize>,
    pub dirty: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SearchMode {
    Simple,
    Regex,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReplaceMode {
    Simple,
    Regex,
}

impl App {
    pub fn new(project_root: PathBuf) -> anyhow::Result<Self> {
        Ok(Self {
            project_root,
            search_input: String::new(),
            replace_input: String::new(),
            input_mode: InputMode::Search,
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            file_results: Vec::new(),
            selected_file_idx: 0,
            selected_match_idx: None,
            dirty: true,
        })
    }

    pub fn perform_search(&mut self) -> anyhow::Result<()> {
        if self.search_input.is_empty() {
            self.file_results.clear();
            return Ok(());
        }

        let searcher = FileSearcher::new(self.project_root.clone())?;
        let matches = match self.search_mode {
            SearchMode::Simple => searcher.search_simple(&self.search_input)?,
            SearchMode::Regex => searcher.search_regex(&self.search_input)?,
        };

        // Group matches by file
        let mut files_map: std::collections::HashMap<PathBuf, Vec<SearchMatch>> = std::collections::HashMap::new();
        for m in matches {
            files_map.entry(m.file.clone())
                .or_insert_with(Vec::new)
                .push(m);
        }

        self.file_results = files_map
            .into_iter()
            .map(|(path, matches)| FileResult {
                path,
                matches,
                selected: false,
                expanded: true,
            })
            .collect();

        // Sort by path
        self.file_results.sort_by(|a, b| a.path.cmp(&b.path));

        self.selected_file_idx = 0;
        self.selected_match_idx = None;
        self.dirty = true;
        Ok(())
    }

    pub fn get_preview(&self) -> Option<String> {
        if self.file_results.is_empty() {
            return None;
        }

        let file_result = &self.file_results[self.selected_file_idx];
        if file_result.matches.is_empty() {
            return None;
        }

        let file_content = std::fs::read_to_string(&file_result.path).ok()?;
        let mut result = String::new();

        for (i, line) in file_content.lines().enumerate() {
            let line_num = i + 1;

            // Check if any matches are on this line
            let mut modified_line = line.to_string();
            let mut has_match_on_line = false;

            for m in &file_result.matches {
                if m.line_number == line_num {
                    has_match_on_line = true;
                    modified_line = apply_replacement(line, &self.search_input, &self.replace_input)?;
                }
            }

            if has_match_on_line {
                result.push_str(&format!("{:4} {}\n", line_num, modified_line));
            }
        }

        if result.is_empty() {
            None
        } else {
            Some(result)
        }
    }

    pub fn cycle_search_mode(&mut self) {
        self.search_mode = match self.search_mode {
            SearchMode::Simple => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        };
    }

    pub fn cycle_replace_mode(&mut self) {
        self.replace_mode = match self.replace_mode {
            ReplaceMode::Simple => ReplaceMode::Regex,
            ReplaceMode::Regex => ReplaceMode::Simple,
        };
    }

    pub fn next_pane(&mut self) {
        self.input_mode = match self.input_mode {
            InputMode::Search => InputMode::Replace,
            InputMode::Replace => InputMode::List,
            InputMode::List => InputMode::Search,
        };
    }

    pub fn prev_pane(&mut self) {
        self.input_mode = match self.input_mode {
            InputMode::Search => InputMode::List,
            InputMode::Replace => InputMode::Search,
            InputMode::List => InputMode::Replace,
        };
    }
}

fn apply_replacement(line: &str, search: &str, replace: &str) -> Option<String> {
    Some(line.replace(search, replace))
}
