use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct Config {
    #[serde(default)]
    pub keybindings: HashMap<String, String>,
}

impl Config {
    pub fn default() -> Self {
        Self {
            keybindings: [
                ("<Ctrl-d>".to_string(), "Quit".to_string()),
                ("<Ctrl-c>".to_string(), "Quit".to_string()),
                ("<Ctrl-z>".to_string(), "Suspend".to_string()),
                ("<Ctrl-r>".to_string(), "Refresh".to_string()),
                ("<Tab>".to_string(), "LoopOverTabs".to_string()),
                ("<Backtab>".to_string(), "BackLoopOverTabs".to_string()),
                ("<Ctrl-o>".to_string(), "ProcessReplace".to_string()),
                ("<Ctrl-b>".to_string(), "ShowHelp".to_string()),
            ].iter().cloned().collect(),
        }
    }

    pub fn load() -> anyhow::Result<Self> {
        let config_path = Self::config_path()?;
        if config_path.exists() {
            let content = std::fs::read_to_string(&config_path)?;
            Ok(serde_json5::from_str(&content).unwrap_or_else(|_| Self::default()))
        } else {
            Ok(Self::default())
        }
    }

    fn config_path() -> anyhow::Result<PathBuf> {
        let config_dir = dirs::config_dir()
            .ok_or_else(|| anyhow::anyhow!("Cannot determine config directory"))?
            .join("serpl");
        Ok(config_dir.join("config.json5"))
    }
}
