use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    Terminal,
};
use std::io;
use crate::app::{App, InputMode};
use crate::ui;

pub struct Tui {
    terminal: Terminal<CrosstermBackend<io::Stdout>>,
    help_visible: bool,
    help_tab: usize,
}

impl Tui {
    pub fn new() -> anyhow::Result<Self> {
        enable_raw_mode()?;
        let mut stdout = io::stdout();
        execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
        let backend = CrosstermBackend::new(stdout);
        let terminal = Terminal::new(backend)?;

        Ok(Self {
            terminal,
            help_visible: false,
            help_tab: 0,
        })
    }

    pub async fn run(&mut self, mut app: App) -> anyhow::Result<()> {
        loop {
            self.terminal.draw(|f| {
                if self.help_visible {
                    ui::draw(f, &app);
                    ui::draw_help(f, self.help_tab);
                } else {
                    ui::draw(f, &app);
                }
            })?;

            if event::poll(std::time::Duration::from_millis(100))? {
                if let Event::Key(key) = event::read()? {
                    if self.help_visible {
                        match key.code {
                            KeyCode::Esc => {
                                self.help_visible = false;
                            }
                            KeyCode::Right => {
                                self.help_tab = (self.help_tab + 1) % 2;
                            }
                            KeyCode::Left => {
                                self.help_tab = if self.help_tab == 0 { 1 } else { 0 };
                            }
                            _ => {}
                        }
                    } else {
                        match key.code {
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                break;
                            }
                            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                break;
                            }
                            KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                self.help_visible = true;
                                self.help_tab = 0;
                            }
                            KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if app.input_mode == InputMode::Search {
                                    app.cycle_search_mode();
                                } else if app.input_mode == InputMode::Replace {
                                    app.cycle_replace_mode();
                                }
                            }
                            KeyCode::Char('o') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                // Replace all
                                self.process_replace_all(&mut app)?;
                            }
                            KeyCode::Tab => {
                                app.next_pane();
                            }
                            KeyCode::BackTab => {
                                app.prev_pane();
                            }
                            _ => {
                                self.handle_input(&mut app, key)?;
                            }
                        }
                    }
                }
            }
        }

        self.cleanup()?;
        Ok(())
    }

