            file_name = file_path.relative_to(self.state.project_root) if file_path.is_relative_to(self.state.project_root) else file_path
            text = f"{file_name} ({len(matches)})"

            attr = curses.A_REVERSE if i == self.state.selected_file_idx else curses.A_NORMAL
            try:
                stdscr.attron(attr)
                stdscr.addstr(list_y + 1 + i, left_x + 1, text[:left_width - 2])
                stdscr.attroff(attr)
