            if i >= height - 3:
                break
            try:
                stdscr.addstr(1 + i, preview_x + 1, line[:right_width - 2])
            except:
                pass

        # Draw status bar
        status_y = height - 1
        if self.state.input_mode == 0:
            status = "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
        elif self.state.input_mode == 1:
            status = "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
        else:
            status = "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"

        try:
            stdscr.attron(curses.color_pair(2))
            stdscr.addstr(status_y, 0, status[:width])
            stdscr.attroff(curses.color_pair(2))
        except:
            pass

        # Set cursor position
        if self.state.input_mode == 0:
            stdscr.move(1, 1 + len(self.state.search_input))
        elif self.state.input_mode == 1:
            stdscr.move(4, 1 + len(self.state.replace_input))

    def draw_box(self, stdscr, y: int, x: int, height: int, width: int, title: str = "", active: bool = False, right_title: str = ""):
        """Draw a box"""
        # Top line
        try:
            stdscr.addstr(y, x, "╭" + "─" * (width - 2) + "╮")
        except:
            stdscr.addstr(y, x, "+" + "-" * (width - 2) + "+")

        # Add title
        try:
            title_str = f" {title} "
            stdscr.addstr(y, x + 1, title_str)
        except:
            pass

        # Add right title if provided
        if right_title:
            try:
                right_title_str = f" {right_title} "
                stdscr.addstr(y, x + width - len(right_title_str) - 1, right_title_str)
            except:
                pass

        # Color the border if active
        if active:
            try:
                for i in range(y, y + height):
                    stdscr.attron(curses.color_pair(1))
                    stdscr.attroff(curses.color_pair(1))
            except:
                pass

        # Side lines
        for i in range(1, height - 1):
            try:
                stdscr.addstr(y + i, x, "│")
                stdscr.addstr(y + i, x + width - 1, "│")
            except:
                pass

        # Bottom line
        try:
            stdscr.addstr(y + height - 1, x, "╰" + "─" * (width - 2) + "╯")
        except:
            stdscr.addstr(y + height - 1, x, "+" + "-" * (width - 2) + "+")

    def draw_text_in_box(self, stdscr, y: int, x: int, text: str):
        """Draw text inside a box"""
        try:
            stdscr.addstr(y, x, text)
        except:
            pass

    def draw_help(self, stdscr, height: int, width: int):
        """Draw help popup"""
        popup_width = (width * 80) // 100
        popup_height = (height * 80) // 100
        popup_x = (width - popup_width) // 2
        popup_y = (height - popup_height) // 2

        # Draw box
        self.draw_box(stdscr, popup_y, popup_x, popup_height, popup_width)

        # Draw tabs
        tabs = ["[1] Global", "[2] Navigation"]
        tab_str = "  ".join(tabs)
        try:
            stdscr.addstr(popup_y + 1, popup_x + 2, tab_str)
        except:
            pass

        # Draw content
        if self.state.help_tab == 0:
            content = [
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
            ]
        else:
            content = [
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
            ]

        for i, line in enumerate(content):
            try:
                stdscr.addstr(popup_y + 3 + i, popup_x + 2, line[:popup_width - 4])
            except:
                pass

    def handle_input(self, ch: int, stdscr):
        """Handle input"""
        # Ctrl+C or Ctrl+D
        if ch == 3 or ch == 4:
            raise KeyboardInterrupt()

        # Ctrl+B (help)
        if ch == 2:
            self.state.help_visible = True
            self.state.help_tab = 0
            return

        # Ctrl+N (toggle mode)
        if ch == 14:
            if self.state.input_mode == 0:
                self.state.search_mode = 1 - self.state.search_mode
            elif self.state.input_mode == 1:
                self.state.replace_mode = 1 - self.state.replace_mode
            return

        # Ctrl+O (process replace all)
        if ch == 15:
            self.process_replace_all()
            return

        # Tab (next pane)
        if ch == 9:
            self.state.input_mode = (self.state.input_mode + 1) % 3
            return

        # Backtab (previous pane)
        if ch == 353:
            self.state.input_mode = (self.state.input_mode - 1) % 3
            return

        # Mode-specific handling
        if self.state.input_mode == 0:  # Search mode
            if ch == 10:  # Enter
                self.state.perform_search()
            elif ch == 127 or ch == 8:  # Backspace
                self.state.search_input = self.state.search_input[:-1]
                self.state.perform_search()
            elif 32 <= ch < 127:
                self.state.search_input += chr(ch)
                self.state.perform_search()

        elif self.state.input_mode == 1:  # Replace mode
            if ch == 127 or ch == 8:  # Backspace
                self.state.replace_input = self.state.replace_input[:-1]
            elif 32 <= ch < 127:
                self.state.replace_input += chr(ch)

        elif self.state.input_mode == 2:  # List mode
            if ch == ord('j') or ch == curses.KEY_DOWN:
                if self.state.selected_file_idx < len(self.state.file_results) - 1:
                    self.state.selected_file_idx += 1
            elif ch == ord('k') or ch == curses.KEY_UP:
                if self.state.selected_file_idx > 0:
                    self.state.selected_file_idx -= 1
            elif ch == ord('g') or ch == ord('h') or ch == curses.KEY_LEFT:
                self.state.selected_file_idx = 0
            elif ch == ord('G') or ch == ord('l') or ch == curses.KEY_RIGHT:
                if self.state.file_results:
                    self.state.selected_file_idx = len(self.state.file_results) - 1
            elif ch == ord('r'):
                self.replace_file()
            elif ch == ord('d'):
                if self.state.file_results:
                    self.state.file_results.pop(self.state.selected_file_idx)
                    if self.state.selected_file_idx >= len(self.state.file_results) and self.state.selected_file_idx > 0:
                        self.state.selected_file_idx -= 1
            elif ch == 10:  # Enter
                pass

    def handle_help_input(self, ch: int):
        """Handle help popup input"""
        if ch == 27:  # Esc
            self.state.help_visible = False
        elif ch == curses.KEY_RIGHT:
            self.state.help_tab = (self.state.help_tab + 1) % 2
        elif ch == curses.KEY_LEFT:
            self.state.help_tab = (self.state.help_tab - 1) % 2
        elif ch == ord('q'):
            self.state.help_visible = False

    def replace_file(self):
        """Replace in selected file"""
        if not self.state.file_results:
            return

        file_path, _ = self.state.file_results[self.state.selected_file_idx]

        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()

            new_content = content.replace(self.state.search_input, self.state.replace_input)

            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(new_content)

            self.state.perform_search()
        except:
            pass

    def process_replace_all(self):
        """Replace all files"""
        for file_path, _ in self.state.file_results:
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                new_content = content.replace(self.state.search_input, self.state.replace_input)

                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(new_content)
            except:
                pass

        self.state.file_results = []

def main():
    parser = ArgumentParser(description="A simple terminal UI for search and replace, ala VS Code")
    parser.add_argument('-p', '--project-root', default='.', help='Path to the project root')
    parser.add_argument('-V', '--version', action='store_true', help='Print version')

    args = parser.parse_args()

    if args.version:
        print("serpl 0.3.4- (2026-04-20)")
        print()
        print("Authors: Yassine Bridi <ybridi@gmail.com>")
        print()
        config_dir = Path.home() / '.config' / 'serpl'
        print(f"Config directory: {config_dir}")
        return

    state = AppState(args.project_root)
    tui = TUI(state)

    try:
        curses.wrapper(tui.run)
    except KeyboardInterrupt:
        pass

if __name__ == '__main__':
    main()
