        self.search_mode = 0  # 0=simple, 1=regex
        self.replace_mode = 0  # 0=simple, 1=regex
        self.file_results = []
        self.selected_file_idx = 0
        self.selected_match_idx = None
        self.help_visible = False
        self.help_tab = 0

    def perform_search(self):
        """Perform search and update results"""
        if not self.search_input:
            self.file_results = []
            return

        searcher = FileSearcher(self.project_root)
        if self.search_mode == 0:  # Simple
            matches = searcher.search_simple(self.search_input)
        else:  # Regex
            matches = searcher.search_regex(self.search_input)

        # Group matches by file
        files_dict = {}
        for match in matches:
            if match.file not in files_dict:
                files_dict[match.file] = []
            files_dict[match.file].append(match)

        # Convert to list and sort
        self.file_results = [
            (file_path, file_matches)
            for file_path, file_matches in sorted(files_dict.items())
        ]
        self.selected_file_idx = 0
        self.selected_match_idx = None

