#!/usr/bin/env python3
"""
serpl - A simple terminal UI for search and replace
"""
import sys
import os
import re
import curses
import json5
from pathlib import Path
from dataclasses import dataclass
from typing import List, Dict, Optional, Tuple
from argparse import ArgumentParser
import logging

# Set up logging
logging.basicConfig(filename='/tmp/serpl_debug.log', level=logging.DEBUG)

@dataclass
class SearchMatch:
    file: Path
    line_number: int
    column: int
    matched_text: str

class FileSearcher:
    def __init__(self, root: Path):
        self.root = Path(root)

    def should_skip(self, path: Path) -> bool:
        """Check if a file/directory should be skipped"""
        # Skip hidden files
        if path.name.startswith('.'):
            return True
        # Skip common directories
        if path.name in {'node_modules', 'target', '.git', '.venv', 'dist', 'build', '__pycache__'}:
            return True
        return False

    def search_simple(self, pattern: str) -> List[SearchMatch]:
        """Search using simple string matching"""
        results = []

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        pos = 0
                        while True:
                            pos = line.find(pattern, pos)
                            if pos == -1:
                                break
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=pos,
                                matched_text=pattern
                            ))
                            pos += len(pattern)
            except (IOError, UnicodeDecodeError):
                pass

        return results

    def search_regex(self, pattern: str) -> List[SearchMatch]:
        """Search using regex"""
        results = []

        try:
            regex = re.compile(pattern)
        except re.error:
            return results

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        for match in regex.finditer(line):
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=match.start(),
                                matched_text=match.group(0)
                            ))
            except (IOError, UnicodeDecodeError):
                pass

        return results

class Config:
    def __init__(self):
        self.keybindings = {}
        self.load()

    def load(self):
        """Load config from ~/.config/serpl/config.json5"""
        config_dir = Path.home() / '.config' / 'serpl'
        config_file = config_dir / 'config.json5'

        if config_file.exists():
            try:
                with open(config_file, 'r') as f:
                    config = json5.load(f)
                    self.keybindings = config.get('keybindings', {})
            except:
                pass

class AppState:
    def __init__(self, project_root: Path):
        self.project_root = Path(project_root)
        self.search_input = ""
        self.replace_input = ""
        self.input_mode = 0  # 0=search, 1=replace, 2=list
        self.search_mode = 0  # 0=simple, 1=regex
        self.replace_mode = 0  # 0=simple, 1=regex
        self.file_results = []
        self.selected_file_idx = 0
        self.selected_match_idx = None
        self.help_visible = False
        self.help_tab = 0

    def perform_search(self):
        """Perform search and update results"""
        if not self.search_input:
            self.file_results = []
            return

        searcher = FileSearcher(self.project_root)
        if self.search_mode == 0:  # Simple
            matches = searcher.search_simple(self.search_input)
        else:  # Regex
            matches = searcher.search_regex(self.search_input)

        # Group matches by file
        files_dict = {}
        for match in matches:
            if match.file not in files_dict:
                files_dict[match.file] = []
            files_dict[match.file].append(match)

        # Convert to list and sort
        self.file_results = [
            (file_path, file_matches)
            for file_path, file_matches in sorted(files_dict.items())
        ]
        self.selected_file_idx = 0
        self.selected_match_idx = None

    def get_preview(self) -> str:
        """Get preview for selected file"""
        if not self.file_results:
            return ""

        file_path, matches = self.file_results[self.selected_file_idx]

        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except:
            return ""

        preview_lines = []
        matched_line_numbers = {m.line_number for m in matches}

        for line_num, line in enumerate(content.split('\n'), 1):
            if line_num in matched_line_numbers:
                # Apply replacement
                modified_line = line.replace(self.search_input, self.replace_input)
                preview_lines.append(f"{line_num:4} {modified_line}")

