logging.basicConfig(filename='/tmp/serpl_debug.log', level=logging.DEBUG)

@dataclass
class SearchMatch:
    file: Path
    line_number: int
    column: int
    matched_text: str

class FileSearcher:
    def __init__(self, root: Path):
        self.root = Path(root)

    def should_skip(self, path: Path) -> bool:
        """Check if a file/directory should be skipped"""
        # Skip hidden files
        if path.name.startswith('.'):
            return True
        # Skip common directories
        if path.name in {'node_modules', 'target', '.git', '.venv', 'dist', 'build', '__pycache__'}:
            return True
        return False

    def search_simple(self, pattern: str) -> List[SearchMatch]:
        """Search using simple string matching"""
        results = []

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        pos = 0
                        while True:
                            pos = line.find(pattern, pos)
                            if pos == -1:
                                break
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=pos,
                                matched_text=pattern
                            ))
                            pos += len(pattern)
            except (IOError, UnicodeDecodeError):
                pass

        return results

    def search_regex(self, pattern: str) -> List[SearchMatch]:
        """Search using regex"""
        results = []

        try:
            regex = re.compile(pattern)
        except re.error:
            return results

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        for match in regex.finditer(line):
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=match.start(),
                                matched_text=match.group(0)
                            ))
            except (IOError, UnicodeDecodeError):
                pass

        return results

class Config:
    def __init__(self):
        self.keybindings = {}
        self.load()

    def load(self):
        """Load config from ~/.config/serpl/config.json5"""
        config_dir = Path.home() / '.config' / 'serpl'
        config_file = config_dir / 'config.json5'

        if config_file.exists():
            try:
                # Try to parse json5-like format
                with open(config_file, 'r') as f:
                    content = f.read()
                    # Remove comments and trailing commas for JSON compatibility
                    content = re.sub(r'//.*$', '', content, flags=re.MULTILINE)
                    content = re.sub(r',(\s*[}\]])', r'\1', content)
                    config = json.loads(content)
                    self.keybindings = config.get('keybindings', {})
            except:
                pass

class AppState:
    def __init__(self, project_root: Path):
        self.project_root = Path(project_root).absolute()
        self.search_input = ""
        self.replace_input = ""
        self.input_mode = 0  # 0=search, 1=replace, 2=list
        self.search_mode = 0  # 0=simple, 1=regex
        self.replace_mode = 0  # 0=simple, 1=regex
        self.file_results = []
        self.selected_file_idx = 0
        self.selected_match_idx = None
        self.help_visible = False
        self.help_tab = 0

    def perform_search(self):
        """Perform search and update results"""
        if not self.search_input:
            self.file_results = []
            return

        searcher = FileSearcher(self.project_root)
        if self.search_mode == 0:  # Simple
            matches = searcher.search_simple(self.search_input)
        else:  # Regex
            matches = searcher.search_regex(self.search_input)

        # Group matches by file
        files_dict = {}
        for match in matches:
            if match.file not in files_dict:
                files_dict[match.file] = []
            files_dict[match.file].append(match)

        # Convert to list and sort
        self.file_results = [
            (file_path, file_matches)
            for file_path, file_matches in sorted(files_dict.items())
        ]
        self.selected_file_idx = 0
        self.selected_match_idx = None

    def get_preview(self) -> str:
        """Get preview for selected file"""
        if not self.file_results:
            return ""

        file_path, matches = self.file_results[self.selected_file_idx]

        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except:
            return ""

        preview_lines = []
        matched_line_numbers = {m.line_number for m in matches}

        for line_num, line in enumerate(content.split('\n'), 1):
            if line_num in matched_line_numbers:
                # Apply replacement
                modified_line = line.replace(self.search_input, self.replace_input)
                preview_lines.append(f"{line_num:4} {modified_line}")

        return '\n'.join(preview_lines)

class TUI:
    def __init__(self, state: AppState):
        self.state = state
        self.config = Config()

    def run(self, stdscr):
        """Main TUI loop"""
        curses.curs_set(1)
        curses.use_default_colors()

        # Set up colors
        curses.init_pair(1, curses.COLOR_CYAN, -1)  # Active pane
        curses.init_pair(2, curses.COLOR_BLACK, curses.COLOR_WHITE)  # Status bar
        curses.init_pair(3, curses.COLOR_WHITE, curses.COLOR_BLACK)  # Normal
        curses.init_pair(4, curses.COLOR_WHITE, curses.COLOR_BLUE)   # Selection

        stdscr.nodelay(True)
        stdscr.timeout(100)

        while True:
            try:
                stdscr.clear()
                height, width = stdscr.getmaxyx()

                if self.state.help_visible:
                    self.draw_main(stdscr, height, width)
                    self.draw_help(stdscr, height, width)
                else:
                    self.draw_main(stdscr, height, width)

                stdscr.refresh()

                # Handle input
                try:
                    ch = stdscr.getch()
                    if ch == -1:
                        continue

                    if self.state.help_visible:
                        self.handle_help_input(ch)
                    else:
                        self.handle_input(ch, stdscr)
                except curses.error:
                    pass

            except KeyboardInterrupt:
                break
            except Exception as e:
                logging.exception(f"Error: {e}")
                break

    def draw_main(self, stdscr, height: int, width: int):
        """Draw main UI"""
        left_width = width // 3
        right_width = width - left_width - 1

        # Left panel
        left_x = 0
        left_y = 0

        # Draw search box (3 lines)
        self.draw_box(stdscr, left_y, left_x, 3, left_width, "Search", 
                      self.state.input_mode == 0, "Simple" if self.state.search_mode == 0 else "Regex")
        self.draw_text_in_box(stdscr, left_y + 1, left_x + 1, self.state.search_input)

        # Draw replace box (3 lines)
        replace_y = 3
        self.draw_box(stdscr, replace_y, left_x, 3, left_width, "Replace",
                      self.state.input_mode == 1, "Simple" if self.state.replace_mode == 0 else "Regex")
        self.draw_text_in_box(stdscr, replace_y + 1, left_x + 1, self.state.replace_input)

        # Draw results list
        list_y = 6
        list_height = height - list_y - 1
        self.draw_box(stdscr, list_y, left_x, list_height, left_width, "Result List",
                      self.state.input_mode == 2)

        # Draw results
        for i, (file_path, matches) in enumerate(self.state.file_results):
            if i >= list_height - 2:
                break

            try:
                file_name = file_path.relative_to(self.state.project_root)
            except ValueError:
                file_name = file_path

            text = f"{file_name} ({len(matches)})"

            attr = curses.A_REVERSE if i == self.state.selected_file_idx else curses.A_NORMAL
            try:
                if attr == curses.A_REVERSE:
                    stdscr.attron(attr)
                stdscr.addstr(list_y + 1 + i, left_x + 1, text[:left_width - 2])
                if attr == curses.A_REVERSE:
                    stdscr.attroff(attr)
            except:
                pass

        # Draw preview (right side)
        preview_x = left_width + 1
        self.draw_box(stdscr, 0, preview_x, height - 1, right_width, "Preview")

        preview = self.state.get_preview()
        for i, line in enumerate(preview.split('\n')):
            if i >= height - 3:
                break
            try:
                stdscr.addstr(1 + i, preview_x + 1, line[:right_width - 2])
            except:
                pass

        # Draw status bar
        status_y = height - 1
        if self.state.input_mode == 0:
            status = "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
        elif self.state.input_mode == 1:
            status = "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
        else:
            status = "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"

        try:
            stdscr.attron(curses.color_pair(2))
            stdscr.addstr(status_y, 0, status[:width])
            stdscr.attroff(curses.color_pair(2))
        except:
            pass

        # Set cursor position
        if self.state.input_mode == 0:
            try:
                stdscr.move(1, 1 + len(self.state.search_input))
            except:
                pass
        elif self.state.input_mode == 1:
            try:
                stdscr.move(4, 1 + len(self.state.replace_input))
            except:
                pass

    def draw_box(self, stdscr, y: int, x: int, height: int, width: int, title: str = "", active: bool = False, right_title: str = ""):
        """Draw a box"""
        # Top line
        try:
            stdscr.addstr(y, x, "╭" + "─" * (width - 2) + "╮")
        except:
            try:
                stdscr.addstr(y, x, "+" + "-" * (width - 2) + "+")
            except:
                pass

        # Add title
        try:
            title_str = f" {title} "
            stdscr.addstr(y, x + 1, title_str)
        except:
            pass

        # Add right title if provided
        if right_title:
            try:
                right_title_str = f" {right_title} "
                stdscr.addstr(y, x + width - len(right_title_str) - 1, right_title_str)
            except:
                pass

        # Side lines
        for i in range(1, height - 1):
            try:
                stdscr.addstr(y + i, x, "│")
                stdscr.addstr(y + i, x + width - 1, "│")
            except:
                try:
                    stdscr.addstr(y + i, x, "|")
                    stdscr.addstr(y + i, x + width - 1, "|")
                except:
                    pass

        # Bottom line
        try:
            stdscr.addstr(y + height - 1, x, "╰" + "─" * (width - 2) + "╯")
        except:
            try:
                stdscr.addstr(y + height - 1, x, "+" + "-" * (width - 2) + "+")
            except:
                pass

    def draw_text_in_box(self, stdscr, y: int, x: int, text: str):
        """Draw text inside a box"""
        try:
            stdscr.addstr(y, x, text)
        except:
            pass

    def draw_help(self, stdscr, height: int, width: int):
        """Draw help popup"""
        popup_width = max(40, (width * 80) // 100)
        popup_height = max(15, (height * 80) // 100)
        popup_x = (width - popup_width) // 2
        popup_y = (height - popup_height) // 2

        # Draw box
        self.draw_box(stdscr, popup_y, popup_x, popup_height, popup_width)

        # Draw tabs
        tabs = ["[1] Global", "[2] Navigation"]
        tab_str = "  ".join(tabs)
        try:
            stdscr.addstr(popup_y + 1, popup_x + 2, tab_str)
        except:
            pass

        # Draw separator
        try:
            stdscr.addstr(popup_y + 2, popup_x + 1, "─" * (popup_width - 2))
        except:
            try:
                stdscr.addstr(popup_y + 2, popup_x + 1, "-" * (popup_width - 2))
            except:
                pass

        # Draw content
        if self.state.help_tab == 0:
            content = [
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
            ]
        else:
            content = [
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
            ]

        for i, line in enumerate(content):
            try:
                stdscr.addstr(popup_y + 3 + i, popup_x + 2, line[:popup_width - 4])
            except:
                pass

    def handle_input(self, ch: int, stdscr):
        """Handle input"""
        # Ctrl+C or Ctrl+D
        if ch == 3 or ch == 4:
            raise KeyboardInterrupt()

        # Ctrl+B (help)
        if ch == 2:
            self.state.help_visible = True
            self.state.help_tab = 0
            return

        # Ctrl+N (toggle mode)
        if ch == 14:
            if self.state.input_mode == 0:
                self.state.search_mode = 1 - self.state.search_mode
            elif self.state.input_mode == 1:
                self.state.replace_mode = 1 - self.state.replace_mode
            return

        # Ctrl+O (process replace all)
        if ch == 15:
            self.process_replace_all()
            return

        # Tab (next pane)
        if ch == 9:
            self.state.input_mode = (self.state.input_mode + 1) % 3
            return

        # Backtab (previous pane) - typically 353 in ncurses
        if ch == 353 or ch == 27:  # ESC followed by other keys or Backtab
            self.state.input_mode = (self.state.input_mode - 1) % 3
            return

        # Mode-specific handling
        if self.state.input_mode == 0:  # Search mode
            if ch == 10:  # Enter
                self.state.perform_search()
            elif ch == 127 or ch == 8:  # Backspace
                self.state.search_input = self.state.search_input[:-1]
                self.state.perform_search()
            elif 32 <= ch < 127:
                self.state.search_input += chr(ch)
                self.state.perform_search()

        elif self.state.input_mode == 1:  # Replace mode
            if ch == 127 or ch == 8:  # Backspace
                self.state.replace_input = self.state.replace_input[:-1]
            elif 32 <= ch < 127:
                self.state.replace_input += chr(ch)

        elif self.state.input_mode == 2:  # List mode
            if ch == ord('j') or ch == curses.KEY_DOWN:
                if self.state.selected_file_idx < len(self.state.file_results) - 1:
                    self.state.selected_file_idx += 1
            elif ch == ord('k') or ch == curses.KEY_UP:
                if self.state.selected_file_idx > 0:
                    self.state.selected_file_idx -= 1
            elif ch == ord('g') or ch == ord('h') or ch == curses.KEY_LEFT:
                self.state.selected_file_idx = 0
            elif ch == ord('G') or ch == ord('l') or ch == curses.KEY_RIGHT:
                if self.state.file_results:
                    self.state.selected_file_idx = len(self.state.file_results) - 1
            elif ch == ord('r'):
                self.replace_file()
            elif ch == ord('d'):
                if self.state.file_results:
                    self.state.file_results.pop(self.state.selected_file_idx)
                    if self.state.selected_file_idx >= len(self.state.file_results) and self.state.selected_file_idx > 0:
                        self.state.selected_file_idx -= 1
            elif ch == 10:  # Enter
                pass

    def handle_help_input(self, ch: int):
        """Handle help popup input"""
        if ch == 27:  # Esc
            self.state.help_visible = False
        elif ch == curses.KEY_RIGHT:
            self.state.help_tab = (self.state.help_tab + 1) % 2
        elif ch == curses.KEY_LEFT:
            self.state.help_tab = (self.state.help_tab - 1) % 2
        elif ch == ord('q'):
            self.state.help_visible = False

    def replace_file(self):
        """Replace in selected file"""
        if not self.state.file_results:
            return

        file_path, _ = self.state.file_results[self.state.selected_file_idx]

        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()

            new_content = content.replace(self.state.search_input, self.state.replace_input)

            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(new_content)

            self.state.perform_search()
        except:
            pass

    def process_replace_all(self):
        """Replace all files"""
        for file_path, _ in self.state.file_results:
            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()

                new_content = content.replace(self.state.search_input, self.state.replace_input)

                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(new_content)
            except:
                pass

        self.state.file_results = []

def main():
    parser = ArgumentParser(description="A simple terminal UI for search and replace, ala VS Code")
    parser.add_argument('-p', '--project-root', default='.', help='Path to the project root')
    parser.add_argument('-V', '--version', action='store_true', help='Print version')
    parser.add_argument('-h', '--help-flag', action='store_true', help='Show help')

    # Manually parse to handle -V properly
    if len(sys.argv) > 1 and (sys.argv[1] == '-V' or sys.argv[1] == '--version'):
        print("serpl 0.3.4- (2026-04-20)")
        print()
        print("Authors: Yassine Bridi <ybridi@gmail.com>")
        print()
        config_dir = Path.home() / '.config' / 'serpl'
        print(f"Config directory: {config_dir}")
        return

    if len(sys.argv) > 1 and (sys.argv[1] == '-h' or sys.argv[1] == '--help'):
        print("A simple terminal UI for search and replace, ala VS Code")
        print()
        print("Usage: executable [OPTIONS]")
        print()
        print("Options:")
        print("  -p, --project-root <PATH>  Path to the project root [default: .]")
        print("  -h, --help                 Print help")
        print("  -V, --version              Print version")
        return

    project_root = '.'
    for i, arg in enumerate(sys.argv[1:]):
        if arg in ['-p', '--project-root'] and i + 1 < len(sys.argv) - 1:
            project_root = sys.argv[i + 2]

    state = AppState(project_root)
    tui = TUI(state)

    try:
        curses.wrapper(tui.run)
    except KeyboardInterrupt:
        pass

if __name__ == '__main__':
    main()
