        self.config = Config()

    def run(self, stdscr):
        """Main TUI loop"""
        curses.curs_set(1)
        curses.use_default_colors()

        # Set up colors
        curses.init_pair(1, curses.COLOR_CYAN, -1)  # Active pane
        curses.init_pair(2, curses.COLOR_BLACK, curses.COLOR_WHITE)  # Status bar
        curses.init_pair(3, curses.COLOR_WHITE, curses.COLOR_BLACK)  # Normal
        curses.init_pair(4, curses.COLOR_WHITE, curses.COLOR_BLUE)   # Selection

        stdscr.nodelay(True)
        stdscr.timeout(100)

        while True:
            try:
                stdscr.clear()
                height, width = stdscr.getmaxyx()

                if self.state.help_visible:
                    self.draw_main(stdscr, height, width)
                    self.draw_help(stdscr, height, width)
                else:
