        """Draw a box"""
        # Top line
        try:
            stdscr.addstr(y, x, "╭" + "─" * (width - 2) + "╮")
        except:
            try:
                stdscr.addstr(y, x, "+" + "-" * (width - 2) + "+")
            except:
                pass

        # Add title
        try:
            title_str = f" {title} "
            stdscr.addstr(y, x + 1, title_str)
        except:
            pass

        # Add right title if provided
        if right_title:
            try:
                right_title_str = f" {right_title} "
                stdscr.addstr(y, x + width - len(right_title_str) - 1, right_title_str)
            except:
                pass

        # Side lines
        for i in range(1, height - 1):
            try:
                stdscr.addstr(y + i, x, "│")
                stdscr.addstr(y + i, x + width - 1, "│")
            except:
                try:
                    stdscr.addstr(y + i, x, "|")
                    stdscr.addstr(y + i, x + width - 1, "|")
                except:
                    pass

        # Bottom line
        try:
            stdscr.addstr(y + height - 1, x, "╰" + "─" * (width - 2) + "╯")
        except:
            try:
                stdscr.addstr(y + height - 1, x, "+" + "-" * (width - 2) + "+")
            except:
                pass

    def draw_text_in_box(self, stdscr, y: int, x: int, text: str):
        """Draw text inside a box"""
        try:
            stdscr.addstr(y, x, text)
        except:
            pass

    def draw_help(self, stdscr, height: int, width: int):
        """Draw help popup"""
        popup_width = max(40, (width * 80) // 100)
        popup_height = max(15, (height * 80) // 100)
        popup_x = (width - popup_width) // 2
        popup_y = (height - popup_height) // 2

        # Draw box
        self.draw_box(stdscr, popup_y, popup_x, popup_height, popup_width)

        # Draw tabs
        tabs = ["[1] Global", "[2] Navigation"]
        tab_str = "  ".join(tabs)
        try:
            stdscr.addstr(popup_y + 1, popup_x + 2, tab_str)
        except:
            pass

        # Draw separator
        try:
            stdscr.addstr(popup_y + 2, popup_x + 1, "─" * (popup_width - 2))
        except:
            try:
                stdscr.addstr(popup_y + 2, popup_x + 1, "-" * (popup_width - 2))
            except:
                pass

        # Draw content
        if self.state.help_tab == 0:
            content = [
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
            ]
        else:
            content = [
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
            ]

        for i, line in enumerate(content):
            try:
                stdscr.addstr(popup_y + 3 + i, popup_x + 2, line[:popup_width - 4])
            except:
                pass

    def handle_input(self, ch: int, stdscr):
        """Handle input"""
        # Ctrl+C or Ctrl+D
        if ch == 3 or ch == 4:
            raise KeyboardInterrupt()

        # Ctrl+B (help)
        if ch == 2:
            self.state.help_visible = True
            self.state.help_tab = 0
            return

        # Ctrl+N (toggle mode)
        if ch == 14:
            if self.state.input_mode == 0:
                self.state.search_mode = 1 - self.state.search_mode
            elif self.state.input_mode == 1:
                self.state.replace_mode = 1 - self.state.replace_mode
            return

        # Ctrl+O (process replace all)
        if ch == 15:
            self.process_replace_all()
            return

        # Tab (next pane)
        if ch == 9:
            self.state.input_mode = (self.state.input_mode + 1) % 3
            return

        # Backtab (previous pane) - typically 353 in ncurses
        if ch == 353 or ch == 27:  # ESC followed by other keys or Backtab
            self.state.input_mode = (self.state.input_mode - 1) % 3
            return

        # Mode-specific handling
        if self.state.input_mode == 0:  # Search mode
            if ch == 10:  # Enter
                self.state.perform_search()
            elif ch == 127 or ch == 8:  # Backspace
                self.state.search_input = self.state.search_input[:-1]
                self.state.perform_search()
            elif 32 <= ch < 127:
                self.state.search_input += chr(ch)
                self.state.perform_search()

        elif self.state.input_mode == 1:  # Replace mode
            if ch == 127 or ch == 8:  # Backspace
                self.state.replace_input = self.state.replace_input[:-1]
            elif 32 <= ch < 127:
                self.state.replace_input += chr(ch)

        elif self.state.input_mode == 2:  # List mode
            if ch == ord('j') or ch == curses.KEY_DOWN:
                if self.state.selected_file_idx < len(self.state.file_results) - 1:
                    self.state.selected_file_idx += 1
            elif ch == ord('k') or ch == curses.KEY_UP:
                if self.state.selected_file_idx > 0:
                    self.state.selected_file_idx -= 1
            elif ch == ord('g') or ch == ord('h') or ch == curses.KEY_LEFT:
                self.state.selected_file_idx = 0
            elif ch == ord('G') or ch == ord('l') or ch == curses.KEY_RIGHT:
                if self.state.file_results:
