        # Add right title if provided
        if right_title:
            try:
                right_title_str = f" {right_title} "
                stdscr.addstr(y, x + width - len(right_title_str) - 1, right_title_str)
            except:
                pass

        # Side lines
        for i in range(1, height - 1):
            try:
                stdscr.addstr(y + i, x, "│")
                stdscr.addstr(y + i, x + width - 1, "│")
            except:
                try:
                    stdscr.addstr(y + i, x, "|")
                    stdscr.addstr(y + i, x + width - 1, "|")
                except:
                    pass

        # Bottom line
        try:
            stdscr.addstr(y + height - 1, x, "╰" + "─" * (width - 2) + "╯")
