    def handle_input(self, ch: int, stdscr):
        """Handle input"""
        # Ctrl+C or Ctrl+D
        if ch == 3 or ch == 4:
            raise KeyboardInterrupt()

        # Ctrl+B (help)
        if ch == 2:
            self.state.help_visible = True
            self.state.help_tab = 0
            return

        # Ctrl+N (toggle mode)
        if ch == 14:
            if self.state.input_mode == 0:
                self.state.search_mode = 1 - self.state.search_mode
            elif self.state.input_mode == 1:
                self.state.replace_mode = 1 - self.state.replace_mode
            return

        # Ctrl+O (process replace all)
        if ch == 15:
            self.process_replace_all()
            return

        # Tab (next pane)
        if ch == 9:
            self.state.input_mode = (self.state.input_mode + 1) % 3
            return

        # Backtab (previous pane) - typically 353 in ncurses
        if ch == 353 or ch == 27:  # ESC followed by other keys or Backtab
            self.state.input_mode = (self.state.input_mode - 1) % 3
            return

        # Mode-specific handling
        if self.state.input_mode == 0:  # Search mode
            if ch == 10:  # Enter
                self.state.perform_search()
            elif ch == 127 or ch == 8:  # Backspace
                self.state.search_input = self.state.search_input[:-1]
                self.state.perform_search()
            elif 32 <= ch < 127:
                self.state.search_input += chr(ch)
                self.state.perform_search()

        elif self.state.input_mode == 1:  # Replace mode
            if ch == 127 or ch == 8:  # Backspace
                self.state.replace_input = self.state.replace_input[:-1]
            elif 32 <= ch < 127:
                self.state.replace_input += chr(ch)

        elif self.state.input_mode == 2:  # List mode
            if ch == ord('j') or ch == curses.KEY_DOWN:
                if self.state.selected_file_idx < len(self.state.file_results) - 1:
                    self.state.selected_file_idx += 1
            elif ch == ord('k') or ch == curses.KEY_UP:
                if self.state.selected_file_idx > 0:
                    self.state.selected_file_idx -= 1
            elif ch == ord('g') or ch == ord('h') or ch == curses.KEY_LEFT:
                self.state.selected_file_idx = 0
            elif ch == ord('G') or ch == ord('l') or ch == curses.KEY_RIGHT:
                if self.state.file_results:
                    self.state.selected_file_idx = len(self.state.file_results) - 1
            elif ch == ord('r'):
                self.replace_file()
            elif ch == ord('d'):
                if self.state.file_results:
                    self.state.file_results.pop(self.state.selected_file_idx)
                    if self.state.selected_file_idx >= len(self.state.file_results) and self.state.selected_file_idx > 0:
                        self.state.selected_file_idx -= 1
            elif ch == 10:  # Enter
                pass

    def handle_help_input(self, ch: int):
        """Handle help popup input"""
        if ch == 27:  # Esc
            self.state.help_visible = False
        elif ch == curses.KEY_RIGHT:
            self.state.help_tab = (self.state.help_tab + 1) % 2
        elif ch == curses.KEY_LEFT:
            self.state.help_tab = (self.state.help_tab - 1) % 2
        elif ch == ord('q'):
            self.state.help_visible = False

    def replace_file(self):
        """Replace in selected file"""
        if not self.state.file_results:
            return

        file_path, _ = self.state.file_results[self.state.selected_file_idx]

        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()

            new_content = content.replace(self.state.search_input, self.state.replace_input)

            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(new_content)

            self.state.perform_search()
        except:
            pass

    def process_replace_all(self):
        """Replace all files"""
        for file_path, _ in self.state.file_results:
            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()

                new_content = content.replace(self.state.search_input, self.state.replace_input)

                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(new_content)
            except:
                pass

        self.state.file_results = []

def main():
