#!/usr/bin/env python3
"""
serpl - A simple terminal UI for search and replace
"""
import sys
import os
import re
import curses
import json
from pathlib import Path
from dataclasses import dataclass
from typing import List, Dict, Optional, Tuple
from argparse import ArgumentParser
import logging

# Set up logging
logging.basicConfig(filename='/tmp/serpl_debug.log', level=logging.DEBUG)

@dataclass
class SearchMatch:
    file: Path
    line_number: int
    column: int
    matched_text: str

class FileSearcher:
    def __init__(self, root: Path):
        self.root = Path(root)

    def should_skip(self, path: Path) -> bool:
        """Check if a file/directory should be skipped"""
        # Skip hidden files
        if path.name.startswith('.'):
            return True
        # Skip common directories
        if path.name in {'node_modules', 'target', '.git', '.venv', 'dist', 'build', '__pycache__'}:
            return True
        return False

    def search_simple(self, pattern: str) -> List[SearchMatch]:
        """Search using simple string matching"""
        results = []

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        pos = 0
                        while True:
                            pos = line.find(pattern, pos)
                            if pos == -1:
                                break
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=pos,
                                matched_text=pattern
                            ))
                            pos += len(pattern)
            except (IOError, UnicodeDecodeError):
                pass

        return results

    def search_regex(self, pattern: str) -> List[SearchMatch]:
        """Search using regex"""
        results = []

        try:
            regex = re.compile(pattern)
        except re.error:
            return results

        for file_path in self.root.rglob('*'):
            if file_path.is_dir() or self.should_skip(file_path):
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    for line_num, line in enumerate(f, 1):
                        for match in regex.finditer(line):
                            results.append(SearchMatch(
                                file=file_path,
                                line_number=line_num,
                                column=match.start(),
                                matched_text=match.group(0)
                            ))
            except (IOError, UnicodeDecodeError):
                pass

        return results

class Config:
    def __init__(self):
        self.keybindings = {}
        self.load()

    def load(self):
        """Load config from ~/.config/serpl/config.json5"""
        config_dir = Path.home() / '.config' / 'serpl'
        config_file = config_dir / 'config.json5'

        if config_file.exists():
            try:
                # Try to parse json5-like format
                with open(config_file, 'r') as f:
                    content = f.read()
                    # Remove comments and trailing commas for JSON compatibility
                    content = re.sub(r'//.*$', '', content, flags=re.MULTILINE)
                    content = re.sub(r',(\s*[}\]])', r'\1', content)
                    config = json.loads(content)
                    self.keybindings = config.get('keybindings', {})
            except:
                pass

