        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except:
            return ""

        preview_lines = []
        matched_line_numbers = {m.line_number for m in matches}

        for line_num, line in enumerate(content.split('\n'), 1):
            if line_num in matched_line_numbers:
                # Apply replacement
                modified_line = line.replace(self.search_input, self.replace_input)
                preview_lines.append(f"{line_num:4} {modified_line}")

